def count_regular_bracket_sequences(n, s):
    m = len(s)

    # dp[i][j] will store the number of ways to form a regular bracket sequence of length i with j unmatched '('
    dp = [[0] * (m + 1) for _ in range(2 * n + 1)]
    dp[0][0] = 1

    for i in range(1, 2 * n + 1):
        for j in range(i + 1):
            if j > 0:
                dp[i][j] += dp[i - 1][j - 1]
            if j < i:
                dp[i][j] += dp[i - 1][j]
            dp[i][j] %= MOD

    def count_ways_to_place_s():
        total_ways = 0
        for k in range(m + 1):
            left_part_length = n - k
            right_part_length = n - (m - k)
            if left_part_length >= 0 and right_part_length >= 0:
                total_ways += dp[left_part_length][k] * dp[right_part_length][m - k]
                total_ways %= MOD
        return total_ways

    return count_ways_to_place_s()

